[data-chat-canvas]{background-image:radial-gradient(rgba(0,0,0,.28) 1px,transparent 1.6px),radial-gradient(ellipse 31% 26% at 51% 31%,rgba(44,66,200,0.75),rgba(44,66,200,0.34) 45%,transparent 100%),radial-gradient(ellipse 28% 21% at 50% 72%,rgba(210,140,50,0.62),rgba(210,140,50,0.28) 45%,transparent 100%),radial-gradient(ellipse 42% 32% at 50% 56%,rgba(140,28,124,0.62),rgba(140,28,124,0.28) 45%,transparent 100%),radial-gradient(ellipse 16% 32% at 81% 60%,rgba(222,20,64,0.78),rgba(222,20,64,0.35) 45%,transparent 100%),radial-gradient(ellipse 13% 26% at 19% 64%,rgba(190,20,70,0.45),rgba(190,20,70,0.2) 45%,transparent 100%),radial-gradient(ellipse 70% 45% at 50% 100%,rgba(70,16,60,0.7),rgba(70,16,60,0.32) 45%,transparent 100%)!important;background-color:#0b060d!important;background-size:7px 7px,var(--n1s) var(--n1s),160% 160%,var(--n3s) var(--n3s),var(--n4s) var(--n4s),160% 160%,100% 100%!important;background-repeat:repeat,no-repeat,no-repeat,no-repeat,no-repeat,no-repeat,no-repeat!important;background-position:0 0,var(--n1x) var(--n1y),var(--n2x) var(--n2y),var(--n3x) var(--n3y),var(--n4x) var(--n4y),var(--n5x) var(--n5y),0 0;animation:nb1x 17s ease-in-out -5.6s infinite alternate,nb1y 23s ease-in-out -19.3s infinite alternate,nb2x 29s ease-in-out -13.3s infinite alternate,nb2y 19s ease-in-out -2.5s infinite alternate,nb3x 31s ease-in-out -18.3s infinite alternate,nb3y 37s ease-in-out -15.5s infinite alternate,nb4x 13s ease-in-out -9.4s infinite alternate,nb4y 41s ease-in-out -29.1s infinite alternate,nb5x 43s ease-in-out -36.6s infinite alternate,nb5y 47s ease-in-out -0.0s infinite alternate,nb1s 53s ease-in-out -21.2s infinite alternate,nb3s 59s ease-in-out -23.6s infinite alternate,nb4s 61s ease-in-out -24.4s infinite alternate}
@keyframes nb1x{from{--n1x:20%}to{--n1x:80%}}
@keyframes nb1y{from{--n1y:25%}to{--n1y:75%}}
@keyframes nb2x{from{--n2x:25%}to{--n2x:78%}}
@keyframes nb2y{from{--n2y:25%}to{--n2y:75%}}
@keyframes nb3x{from{--n3x:22%}to{--n3x:78%}}
@keyframes nb3y{from{--n3y:28%}to{--n3y:80%}}
@keyframes nb4x{from{--n4x:15%}to{--n4x:85%}}
@keyframes nb4y{from{--n4y:20%}to{--n4y:80%}}
@keyframes nb5x{from{--n5x:30%}to{--n5x:70%}}
@keyframes nb5y{from{--n5y:22%}to{--n5y:78%}}
