[data-workspace-area="conversation"],.messages-timeline-scroll,[data-chat-header]{background:transparent!important}
[data-chat-header]{border-bottom:0!important}
[data-slot="sidebar-inner"]{background:linear-gradient(180deg,rgba(30,16,34,.92),rgba(22,10,24,.94))!important;border:1px solid rgba(255,255,255,.07)!important;border-radius:20px!important;box-shadow:0 20px 60px rgba(0,0,0,.45)}
[data-thread-item]{border-radius:10px!important}
[data-slot="composer-host"]{background:rgba(22,12,24,.62)!important;backdrop-filter:blur(22px) saturate(140%);animation:nbGlow 16s linear infinite}
@keyframes nbGlow{0%,100%{box-shadow:0 0 34px rgba(70,90,230,.18),0 18px 50px rgba(0,0,0,.45)}25%{box-shadow:0 0 34px rgba(170,40,170,.18),0 18px 50px rgba(0,0,0,.45)}50%{box-shadow:0 0 34px rgba(220,30,70,.18),0 18px 50px rgba(0,0,0,.45)}75%{box-shadow:0 0 34px rgba(210,140,50,.17),0 18px 50px rgba(0,0,0,.45)}}
[data-slot="composer-host"]::after{animation:nbEdge 16s linear infinite}
@keyframes nbEdge{0%,100%{border-color:rgba(90,110,255,.4)}25%{border-color:rgba(190,60,200,.42)}50%{border-color:rgba(240,50,90,.42)}75%{border-color:rgba(230,160,70,.42)}}
[data-chat-composer-form] :is(button[type="submit"],button.bg-message-action){background-image:linear-gradient(135deg,#3f55e0,#a0309f 38%,#e0204f 68%,#e8a040)!important;background-size:240% 240%!important;background-position:0 50%;color:#fff!important;box-shadow:0 0 16px rgba(200,50,140,.4)!important;animation:nbBtn 7s ease-in-out infinite alternate}
[data-chat-composer-form] :is(button[type="submit"],button.bg-message-action):disabled{opacity:.5;box-shadow:none!important}
@keyframes nbBtn{to{background-position:100% 50%}}
[data-user-message-bubble]{background:rgba(255,255,255,.08)!important;border:1px solid rgba(255,255,255,.08)!important;backdrop-filter:blur(16px)}
.chat-markdown-codeblock{background:rgba(10,5,12,.7)!important;border:1px solid rgba(255,255,255,.08)!important;backdrop-filter:blur(12px)}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{background:rgba(26,14,28,.92)!important;backdrop-filter:blur(20px);border:1px solid rgba(255,255,255,.09)!important}
::selection{background:rgba(196,80,160,.4)}
::-webkit-scrollbar{width:9px}::-webkit-scrollbar-thumb{background:rgba(255,255,255,.16);border-right:3px solid transparent;background-clip:padding-box;border-radius:9px}
@media (prefers-reduced-motion:reduce){[data-chat-canvas],[data-slot="composer-host"],[data-slot="composer-host"]::after,[data-chat-composer-form] button{animation:none!important}}
